sp_widget.client_script:
function ($scope, $sce) {
  // Render HTML safely (trusted) - ok for hobby/internal use
  $scope.trustedHtml = function (html) {
    if (!html) return "";
    return $sce.trustAsHtml(html);
  };
}

sp_widget.css:
.lib-record-detail .lib-error {
  padding: 12px;
}

.lib-back {
  margin-bottom: 12px;
}

.lib-back-link {
  text-decoration: none;
}

.lib-detail-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: 18px;
}

.lib-detail-cover {
  border: 1px solid rgba(0,0,0,0.12);
  border-radius: 12px;
  background: rgba(0,0,0,0.04);
  overflow: hidden;
  height: 380px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.lib-detail-cover img {
  max-width: 100%;
  max-height: 100%;
  object-fit: cover;
}

.lib-detail-cover-placeholder {
  width: 70%;
  height: 80%;
  border: 1px dashed rgba(0,0,0,0.25);
  border-radius: 10px;
}

.lib-detail-title {
  margin: 0 0 10px 0;
  font-weight: 700;
}

.lib-detail-meta {
  border: 1px solid rgba(0,0,0,0.08);
  border-radius: 10px;
  padding: 10px 12px;
  margin-bottom: 14px;
}

.lib-detail-meta-row {
  display: grid;
  grid-template-columns: 160px 1fr;
  gap: 10px;
  padding: 6px 0;
  border-bottom: 1px solid rgba(0,0,0,0.06);
}

.lib-detail-meta-row:last-child {
  border-bottom: none;
}

.lib-detail-meta-label {
  font-size: 12px;
  color: rgba(0,0,0,0.65);
  font-weight: 600;
}

.lib-detail-meta-value {
  font-size: 13px;
  color: rgba(0,0,0,0.9);
}

.lib-meta-link {
  text-decoration: none;
}

.lib-meta-link:hover {
  text-decoration: underline;
}

.lib-detail-desc-short {
  margin-bottom: 10px;
  color: rgba(0,0,0,0.85);
}

.lib-detail-desc-long {
  color: rgba(0,0,0,0.85);
}

sp_widget.option_schema:
[ { "name": "table", "label": "Table", "type": "string", "default": "x_662888_library_book" }, { "name": "sys_id_param", "label": "URL sys_id param", "type": "string", "default": "sys_id" },
{ "name": "title_field", "label": "Title field", "type": "string", "default": "title" }, { "name": "image_field", "label": "Image field (optional)", "type": "string", "default": "cover" },
{ "name": "meta_fields", "label": "Meta fields (comma-separated)", "type": "string", "default": "author,series,genre,first_published_year,primary_language,status" },
{ "name": "short_description_field", "label": "Short description field (optional)", "type": "string", "default": "description" }, { "name": "long_description_field", "label": "Long description field (optional)", "type": "string", "default": "long_description" },
{ "name": "back_link_page", "label": "Back link page (optional)", "type": "string", "default": "library_browse_books" }, { "name": "back_link_label", "label": "Back link label", "type": "string", "default": "Back to books" }, { "name": "link_map", "label": "Link map (JSON)", "type": "string", "default": "{\"author\":{\"page\":\"library_author\"},\"series\":{\"page\":\"library_series\"},\"genre\":{\"page\":\"library_genre\"}}" }, { "name": "link_field_param", "label": "Link param name", "type": "string", "default": "sys_id" }
]

sp_widget.script:
(function () {
  data.error = "";
  data.record = null;

  var opts = options || {};
  var table = (opts.table || "").trim();
  var sysIdParam = (opts.sys_id_param || "sys_id").trim();

  if (!table) {
    data.error = "Missing option: table";
    return;
  }

  var sysId = (input && input.sys_id) ? ("" + input.sys_id) : ("" + ($sp.getParameter(sysIdParam) || ""));
  sysId = (sysId || "").trim();

  if (!sysId) {
    data.error = "Missing record id";
    return;
  }

  var gr = new GlideRecord(table);
  if (!gr.isValid()) {
    data.error = "Invalid table: " + table;
    return;
  }

  if (!gr.get(sysId)) {
    data.error = "Record not found";
    return;
  }

  var titleField = (opts.title_field || "name").trim();
  var imageField = (opts.image_field || "").trim();
  var shortDescField = (opts.short_description_field || "").trim();
  var longDescField = (opts.long_description_field || "").trim();

  var metaFields = [];
  var metaStr = (opts.meta_fields || "").trim();
  if (metaStr) {
    metaFields = metaStr.split(",").map(function (s) { return s.trim(); }).filter(function (s) { return !!s; });
  }

  // Parse link map JSON: {"author":{"page":"library_author"}, ...}
  var linkMap = {};
  try {
    linkMap = JSON.parse((opts.link_map || "{}").trim() || "{}");
  } catch (e) {
    linkMap = {};
  }
  var linkParam = (opts.link_field_param || "sys_id").trim();

  function safeDisplayValue(fieldName) {
    if (!fieldName) return "";
    if (!gr.isValidField(fieldName)) return "";
    try { return gr.getDisplayValue(fieldName) || ""; }
    catch (e) { return ""; }
  }

  function safeValue(fieldName) {
    if (!fieldName) return "";
    if (!gr.isValidField(fieldName)) return "";
    try { return gr.getValue(fieldName) || ""; }
    catch (e) { return ""; }
  }

  var rec = {
    sys_id: gr.getUniqueValue(),
    title: "",
    image_url: "",
    short_description: "",
    long_description: "",
    meta: [],
    table: table
  };

  rec.title = safeDisplayValue(titleField) || gr.getDisplayValue() || "";

  if (imageField && gr.isValidField(imageField)) {
    rec.image_url = safeDisplayValue(imageField) || "";
  }

  if (shortDescField) rec.short_description = safeDisplayValue(shortDescField) || "";
  if (longDescField) rec.long_description = safeDisplayValue(longDescField) || "";

  for (var i = 0; i < metaFields.length; i++) {
    var f = metaFields[i];
    if (!gr.isValidField(f)) continue;

    var element = gr.getElement(f);
    if (!element) continue;

    var label = element.getLabel();
    var display = safeDisplayValue(f);
    if (!display) continue;

    var metaItem = {
      field: f,
      label: label,
      value: display,
      link: null
    };

    // If reference field AND mapped, make it linkable
    // If mapped in link_map AND field has a value, make it linkable (robust)
    var mapped = linkMap && linkMap[f] && linkMap[f].page;
    if (mapped) {
      var refSysId = safeValue(f); // for Reference fields this is the referenced sys_id
      if (refSysId) {
        metaItem.link = {
          page: linkMap[f].page,
          param: linkParam,
          sys_id: refSysId
        };
      }
    }


    rec.meta.push(metaItem);
  }

  data.back = {
    page: (opts.back_link_page || "").trim(),
    label: (opts.back_link_label || "Back").trim()
  };

  data.record = rec;
})();
